import importlib, json, pkgutil, sys
from pathlib import Path
import pytest
from btc_predictor.research_backtest import input_census as ic

census = ic.discover_decision_path()
roots = set(census.root_paths)
codes = set()
active = set()


def profile(frame, event, arg):
    if event == "call":
        path = f"{frame.f_globals.get('__name__')}.{frame.f_code.co_qualname}"
        if path in roots:
            active.add(id(frame))
        if active:
            code = frame.f_code
            module = frame.f_globals.get("__name__")
            if ic._is_package_source(code.co_filename) and ic.in_scope_module(module):
                codes.add((module, code))
    elif event == "return":
        active.discard(id(frame))


name = sys.argv[1]
sys.setprofile(profile)
if name == "fixtures":
    for info in sorted(pkgutil.iter_modules(importlib.import_module("btc_predictor.tests").__path__), key=lambda i: i.name):
        if info.name.startswith("test_research_backtest_census_trace_g"):
            module = importlib.import_module(f"btc_predictor.tests.{info.name}")
            for thunks in module.FIXTURES.values():
                for thunk in thunks:
                    thunk()
    result = 0
else:
    modules = json.loads(Path(sys.argv[2]).read_text())
    result = pytest.main(["-q", "-p", "no:cacheprovider", *modules])
sys.setprofile(None)
keys = {ic.TracedCode.from_code(module, code).key for module, code in codes}
executed = sorted(path for key, paths in census.nested_by_code.items() if key in keys for path in paths)
Path(sys.argv[-1]).write_text(json.dumps({"executed": executed, "total": len(census.nested), "pytest_exit": int(result)}, indent=1))
print(name, len(executed), "/", len(census.nested))
raise SystemExit(result)

