import ast,inspect,json,importlib
from pathlib import Path
from btc_predictor.research_backtest import input_census as ic
c=ic.discover_decision_path();out={'runs':{},'unexecuted_calls_outside_static':[]}
for name in ('fixtures','owners'):
 raw=json.loads(Path('<measurement directory>/coverage-'+name+'.json').read_text());result={};total=[0,0,0,0]
 for file,data in raw['files'].items():
  tree=ast.parse(Path(file).read_text());module=file[:-3].replace('/','.');spans=[]
  def walk(node,qual=''):
   if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):qual=f'{qual}.{node.name}' if qual else node.name
   path=module+'.'+qual
   if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) and path in c.callables:
    spans.append((node.lineno,node.end_lineno,path,node))
   for child in ast.iter_child_nodes(node):walk(child,qual)
  walk(tree)
  def owner(line):
   matches=[x for x in spans if x[0]<=line<=x[1]]
   return min(matches,key=lambda x:x[1]-x[0]) if matches else None
  lines=set(data['executed_lines'])|set(data['missing_lines']);reached_lines={l for l in lines if owner(l)}
  covered=reached_lines&set(data['executed_lines'])
  missing_arcs=[a for a in data['missing_branches'] if owner(a[0])]
  arcs=[a for a in data['executed_branches']+data['missing_branches'] if owner(a[0])]
  total=[a+b for a,b in zip(total,(len(covered),len(reached_lines),len(arcs)-len(missing_arcs),len(arcs)))]
  result[file]={'reached_lines':[len(covered),len(reached_lines)],'reached_branches':[len(arcs)-len(missing_arcs),len(arcs)],'unexecuted_branches':[[a,b,owner(a)[2],Path(file).read_text().splitlines()[a-1].strip()] for a,b in missing_arcs]}
  # Resolve explicit calls in never-executed statements independently of census call-site list.
  namespace=vars(importlib.import_module(module))
  def resolve(node):
   if isinstance(node,ast.Name):return namespace.get(node.id)
   if isinstance(node,ast.Attribute):
    base=resolve(node.value)
    if inspect.ismodule(base) or inspect.isclass(base):return inspect.getattr_static(base,node.attr,None)
   return None
  for start,end,path,node in spans:
   for sub in ast.walk(node):
    if isinstance(sub,ast.Call) and sub.lineno in data['missing_lines']:
     obj=resolve(sub.func)
     if inspect.isfunction(obj) or inspect.isclass(obj):
      p=f'{obj.__module__}.{obj.__qualname__}'
      if ic.in_scope_module(obj.__module__) and p not in c.callables and p not in c.types:
       out['unexecuted_calls_outside_static'].append([name,file,sub.lineno,path,p])
 out['runs'][name]={'module_totals':raw['totals'],'reached_totals':dict(zip(('covered_lines','statements','covered_branches','branches'),total)),'files':result}
Path('<measurement directory>/coverage-audit.json').write_text(json.dumps(out,indent=2)+'\n')
for n,r in out['runs'].items():print(n,r['reached_totals'])
print('never-executed direct calls outside static:',out['unexecuted_calls_outside_static'])
